#include <cuda.h>
#include <cuda_runtime.h>

__global__ void avg_pool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int kernel_size, int stride, int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int c = tmp % C;
    int n = tmp / C;

    int hstart = oh * stride - padding;
    int wstart = ow * stride - padding;

    float sum = 0.0f;
    for (int kh = 0; kh < kernel_size; kh++) {
        int ih = hstart + kh;
        if (ih < 0 || ih >= H_in) continue;
        for (int kw = 0; kw < kernel_size; kw++) {
            int iw = wstart + kw;
            if (iw < 0 || iw >= W_in) continue;
            sum += input[((n * C + c) * H_in + ih) * W_in + iw];
        }
    }
    // count_include_pad=True: always divide by kernel_size*kernel_size
    output[idx] = sum / (float)(kernel_size * kernel_size);
}

torch::Tensor avg_pool2d_forward_cuda(torch::Tensor x, int64_t kernel_size, int64_t stride, int64_t padding) {
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");

    int N = x.size(0);
    int C = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    int H_out = (H_in + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W_in + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, x.options());

    int total = N * C * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    avg_pool2d_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H_in, W_in,
        H_out, W_out,
        (int)kernel_size, (int)stride, (int)padding
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

